-- Ensure the type column exists
DO $$ 
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' 
      AND table_name = 'timetables' 
      AND column_name = 'type'
  ) THEN
    ALTER TABLE public.timetables ADD COLUMN type TEXT DEFAULT 'lecture' CHECK (type IN ('lecture', 'lab', 'activity', 'remedial'));
  END IF;
END $$;

